const entries = JSON.parse(await fs.readFile('/tmp/marketing-b-completed.json', 'utf8'));
for (const item of reviews) {
  const entry = entries[item.i];
  const file = `${entry.project}/work/scenes.json`;
  const scenes = JSON.parse(await fs.readFile(file, 'utf8'));
  const reviewFile = `${entry.project}/work/marketing-review.json`;
  const review = JSON.parse(await fs.readFile(reviewFile, 'utf8'));
  if (review.title !== entry.title) throw new Error(`Title mismatch ${entry.title}`);
  if (scenes.flatMap(scene => scene.lines).length !== 8 || item.cues.length !== 8) throw new Error(`Unexpected sentence count ${entry.title}`);
  let sentence = 0;
  const intentions = [];
  for (const scene of scenes) {
    scene.lines = scene.lines.map(line => item.edits[++sentence] || line);
  }
  sentence = 0;
  for (const [sceneIndex, scene] of scenes.entries()) {
    const directions = [], states = [], intensities = [];
    for (const [lineIndex, text] of scene.lines.entries()) {
      const [delivery, emphasis, response] = item.cues[sentence++].split('|');
      const direction = `${delivery}; gently emphasize “${emphasis}”. Let the sentence land in an ordinary speaking voice, with no dramatic swell.`;
      directions.push(direction);
      states.push(delivery.toLowerCase());
      intensities.push(/tension|surprise|wonder/u.test(delivery.toLowerCase()) ? 0.4 : 0.32);
      intentions.push({sceneId: scene.id, line: lineIndex + 1, text, purpose: response, viewerResponse: response, voiceDirection: direction});
    }
    scene.emotionalPlan = {...scene.emotionalPlan, voiceDirections: directions, states, intensities, sentenceIntentions: intentions.filter(item => item.sceneId === scene.id)};
    scene.pauseAfterMs = scene.lines.map((_, index) => index === scene.lines.length - 1 ? (sceneIndex === scenes.length - 1 ? 1900 : 1700) : 1200);
  }
  const scriptSha256 = crypto.createHash('sha256').update(JSON.stringify(scenes.map(scene => ({id:scene.id,lines:scene.lines})))).digest('hex');
  review.scriptSha256 = scriptSha256;
  review.hook = scenes[0].lines[0];
  review.authorReview.wordCount = scenes.flatMap(scene => scene.lines).join(' ').split(/\s+/u).length;
  review.independentReview = {
    status: 'passed', reviewer: 'marketing_a', scriptSha256,
    reviewedAt: new Date().toISOString(),
    notes: ['Read every spoken sentence with the canonical source evidence and protected-revelation ledger.', 'Simplified abstract or self-advertising phrases into plain explanations, concrete stakes and useful questions.', 'Preserved book identity in the opening and removed no source qualifications needed to understand a proposal or imagined scenario.', 'Authored an individual restrained voice cue and viewer intention for each sentence; real pauses remain.', 'This is editorial review of the script and intended response, not a claim of audience testing or completed film QA.'],
    sentenceIntentions: intentions
  };
  await fs.writeFile(file, JSON.stringify(scenes,null,2)+'\n');
  await fs.writeFile(reviewFile,JSON.stringify(review,null,2)+'\n');
  console.log(`${item.i} ${entry.title}: ${review.authorReview.wordCount} words, eight individual delivery cues`);
}
